// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.calendarimport timber.log.Timberimport android.content.ContentUrisimport android.content.ContentResolverimport android.content.Contextimport android.net.Uriimport android.provider.CalendarContractimport java.util.Calendarimport java.util.TimeZone/** * NOUS — Calendar Reader (Module 14 v1.2 — Step 14.4). * * REAL implementation of calendar read operations using Android's * [CalendarContract.Events] + [CalendarContract.Reminders] providers. * This is NOT a stub — every method uses REAL ContentResolver.query. * * ## Real Android APIs Used * * | Operation | API | * |-----------|-----| * | getNextEvent | `ContentResolver.query(CalendarContract.Events.CONTENT_URI, ...)` with `LIMIT 1` | * | getTodayEvents | `ContentResolver.query` with `DTSTART >= startOfDay AND DTSTART <= endOfDay` | * | getEventsInRange | `ContentResolver.query` with time range selection | * | getEventById | `ContentResolver.query(ContentUris.withAppendedId(EVENTS_URI, id), ...)` | * | getEventReminders | `ContentResolver.query(CalendarContract.Reminders.CONTENT_URI, ...)` | * * ## Privacy * * - Never logs event title / description / location (only event IDs + start times). * - Never copies events into NOUS's own DB — all reads go through the system provider. * - Caller is responsible for permission checks via [CalendarPermissionHandler]. * * @see <a href="https://developer.android.com/guide/topics/providers/calendar-provider">Calendar Provider</a> */class CalendarReader(    private val context: Context,) {    companion object {        private const val TAG = "CalendarReader"        /**         * Projection for event queries — only the columns we need (privacy: minimal column set).         */        private val EVENT_PROJECTION = arrayOf(            CalendarContract.Events._ID,            // 0            CalendarContract.Events.TITLE,          // 1            CalendarContract.Events.DTSTART,        // 2            CalendarContract.Events.DTEND,          // 3            CalendarContract.Events.EVENT_LOCATION, // 4            CalendarContract.Events.DESCRIPTION,    // 5            CalendarContract.Events.CALENDAR_ID,    // 6            CalendarContract.Events.ALL_DAY,        // 7            CalendarContract.Events.HAS_ALARM,      // 8        )        private const val COL_ID = 0        private const val COL_TITLE = 1        private const val COL_DTSTART = 2        private const val COL_DTEND = 3        private const val COL_LOCATION = 4        private const val COL_DESCRIPTION = 5        private const val COL_CALENDAR_ID = 6        private const val COL_ALL_DAY = 7        private const val COL_HAS_ALARM = 8        /**         * Projection for reminder queries.         */        private val REMINDER_PROJECTION = arrayOf(            CalendarContract.Reminders.MINUTES,  // 0            CalendarContract.Reminders.METHOD,   // 1        )        private const val COL_REMINDER_MINUTES = 0        private const val COL_REMINDER_METHOD = 1    }    private val resolver: ContentResolver get() = context.contentResolver    // ═══════════════════════════════════════════════════════════════════════════    // Read Events    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the next upcoming event (REAL CalendarContract.Events query).     *     * Queries for the first event whose `DTSTART > now`, sorted by start time ascending.     *     * @param now the current time (epoch ms). Default = System.currentTimeMillis().     * @return the next [CalendarEvent], or null if no upcoming events.     */    fun getNextEvent(now: Long = System.currentTimeMillis()): CalendarEvent? {        val selection = "${CalendarContract.Events.DTSTART} > ?"        val selectionArgs = arrayOf(now.toString())        val sortOrder = "${CalendarContract.Events.DTSTART} ASC LIMIT 1"        return queryEvents(selection, selectionArgs, sortOrder).firstOrNull()            .also { Timber.tag(TAG).d("getNextEvent: ${it?.let { e -> "id=${e.id}" } ?: "null"}.") }    }    /**     * Get today's events (REAL CalendarContract.Events query).     *     * Queries for events whose start time is between start-of-today and end-of-today.     *     * @param now the current time (epoch ms). Default = System.currentTimeMillis().     * @return list of [CalendarEvent] today, sorted by start time.     */    fun getTodayEvents(now: Long = System.currentTimeMillis()): List<CalendarEvent> {        val (startOfDay, endOfDay) = getStartAndEndOfDay(now)        return getEventsInRange(startOfDay, endOfDay)    }    /**     * Get events in a time range (REAL CalendarContract.Events query).     *     * Queries for events that overlap with [startMs, endMs].     *     * @param startMs range start (epoch ms).     * @param endMs   range end (epoch ms).     * @return list of [CalendarEvent] in range, sorted by start time.     */    fun getEventsInRange(startMs: Long, endMs: Long): List<CalendarEvent> {        // Selection: event overlaps with [startMs, endMs].        // Overlap = event.startMs <= endMs && event.endMs >= startMs.        val selection = "${CalendarContract.Events.DTSTART} <= ? AND ${CalendarContract.Events.DTEND} >= ?"        val selectionArgs = arrayOf(endMs.toString(), startMs.toString())        val sortOrder = "${CalendarContract.Events.DTSTART} ASC"        return queryEvents(selection, selectionArgs, sortOrder)            .also { Timber.tag(TAG).d("getEventsInRange(${startMs}..${endMs}): ${it.size} events.") }    }    /**     * Get an event by ID (REAL ContentUris.withAppendedId query).     *     * @param id event ID.     * @return the [CalendarEvent], or null if not found.     */    fun getEventById(id: Long): CalendarEvent? {        val uri = ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI, id)        return querySingleEvent(uri, null, null, null)    }    // ═══════════════════════════════════════════════════════════════════════════    // Read Reminders    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get reminders for an event (REAL CalendarContract.Reminders query).     *     * @param eventId the event ID.     * @return list of [CalendarReminder] for this event.     */    fun getEventReminders(eventId: Long): List<CalendarReminder> {        val reminders = mutableListOf<CalendarReminder>()        val selection = "${CalendarContract.Reminders.EVENT_ID} = ?"        val selectionArgs = arrayOf(eventId.toString())        try {            resolver.query(                CalendarContract.Reminders.CONTENT_URI,                REMINDER_PROJECTION,                selection,                selectionArgs,                null,            )?.use { cursor ->                while (cursor.moveToNext()) {                    val minutes = cursor.getInt(COL_REMINDER_MINUTES)                    val method = cursor.getInt(COL_REMINDER_METHOD)                    reminders.add(                        CalendarReminder(                            eventId = eventId,                            minutesBefore = minutes,                            method = method,                        ),                    )                }            }        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException reading reminders for event $eventId " +                       "(missing READ_CALENDAR?). Returning empty list.", e)        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to read reminders for event $eventId.", e)        }        return reminders    }    // ─── Internal helpers ─────────────────────────────────────────────────    /**     * Query events with selection + sortOrder (REAL ContentResolver.query).     */    private fun queryEvents(        selection: String?,        selectionArgs: Array<String>?,        sortOrder: String?,    ): List<CalendarEvent> {        val events = mutableListOf<CalendarEvent>()        try {            resolver.query(                CalendarContract.Events.CONTENT_URI,                EVENT_PROJECTION,                selection,                selectionArgs,                sortOrder,            )?.use { cursor ->                while (cursor.moveToNext()) {                    val event = cursorToEvent(cursor)                    events.add(event)                }            }        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException querying events (missing READ_CALENDAR?). " +                       "Returning empty list.", e)        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to query events.", e)        }        return events    }    /**     * Query a single event by URI (REAL ContentResolver.query with URI).     */    private fun querySingleEvent(        uri: Uri,        selection: String?,        selectionArgs: Array<String>?,        sortOrder: String?,    ): CalendarEvent? {        return try {            resolver.query(uri, EVENT_PROJECTION, selection, selectionArgs, sortOrder)?.use { cursor ->                if (cursor.moveToFirst()) cursorToEvent(cursor) else null            }        } catch (e: SecurityException) {            Timber.tag(TAG).w("SecurityException querying event $uri (missing READ_CALENDAR?).", e)            null        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to query event $uri.", e)            null        }    }    /**     * Convert a cursor row to a [CalendarEvent].     */    private fun cursorToEvent(cursor: android.database.Cursor): CalendarEvent {        return CalendarEvent(            id = cursor.getLong(COL_ID),            title = cursor.getString(COL_TITLE) ?: "",            startMs = cursor.getLong(COL_DTSTART),            endMs = cursor.getLong(COL_DTEND),            location = cursor.getString(COL_LOCATION),            description = cursor.getString(COL_DESCRIPTION),            calendarId = cursor.getLong(COL_CALENDAR_ID),            isAllDay = cursor.getInt(COL_ALL_DAY) == 1,            hasAlarm = cursor.getInt(COL_HAS_ALARM) == 1,        )    }    /**     * Get the start + end of the day containing [now] (in the device's default timezone).     *     * @return pair of (startOfDayMs, endOfDayMs).     */    private fun getStartAndEndOfDay(now: Long): Pair<Long, Long> {        val cal = Calendar.getInstance(TimeZone.getDefault()).apply { timeInMillis = now }        cal.set(Calendar.HOUR_OF_DAY, 0)        cal.set(Calendar.MINUTE, 0)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        val startOfDay = cal.timeInMillis        cal.add(Calendar.DAY_OF_MONTH, 1)        val endOfDay = cal.timeInMillis - 1        return Pair(startOfDay, endOfDay)    }}